// Package push sends Web Push (VAPID) notifications and manages browser
// push subscriptions. Keys come from VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY
// (base64url, generated by `webpush generate_keys`); without them the
// sender is a no-op and subscriptions are not advertised.
package push

import (
	"bytes"
	"context"
	"crypto/ecdh"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/SherClockHolmes/webpush-go"
)

type Subscription struct {
	Endpoint string
	P256DH   string
	Auth     string
}

var (
	keysOnce    sync.Once
	vapidPublic string
	vapidPriv   string
	contact     string
)

func loadKeys() {
	vapidPublic = strings.TrimSpace(getenv("VAPID_PUBLIC_KEY"))
	vapidPriv = strings.TrimSpace(getenv("VAPID_PRIVATE_KEY"))
	contact = normalizeSubscriber(getenv("VAPID_CONTACT"))
	if contact == "" {
		contact = "admin@velm.dev"
	}
}

// normalizeSubscriber returns the contact in the form webpush-go expects: a
// bare e-mail address or an https: URL.
//
// The library prepends "mailto:" to anything that does not start with
// "https:", so passing an already-correct "mailto:" value (the conventional
// way to write a VAPID subject, and what every Web Push guide shows) produces
// the invalid claim sub="mailto:mailto:user@example.com". APNs answers that
// with 403 BadJwtToken — an error that names the token, not the cause, and
// that no amount of key rotation fixes.
func normalizeSubscriber(contact string) string {
	contact = strings.TrimSpace(contact)
	for strings.HasPrefix(strings.ToLower(contact), "mailto:") {
		contact = strings.TrimSpace(contact[len("mailto:"):])
	}
	return contact
}

// KeypairError reports whether VAPID_PUBLIC_KEY and VAPID_PRIVATE_KEY are a
// matching pair. A mismatch is otherwise silent: /api/push/config advertises
// the public key, browsers subscribe against it, and every send is rejected
// because the JWT is signed with a private key that does not belong to the k=
// parameter carried alongside it.
func KeypairError() error {
	keysOnce.Do(loadKeys)
	if vapidPublic == "" || vapidPriv == "" {
		return nil
	}
	priv, err := base64.RawURLEncoding.DecodeString(vapidPriv)
	if err != nil {
		return fmt.Errorf("VAPID_PRIVATE_KEY is not valid base64url: %w", err)
	}
	pub, err := base64.RawURLEncoding.DecodeString(vapidPublic)
	if err != nil {
		return fmt.Errorf("VAPID_PUBLIC_KEY is not valid base64url: %w", err)
	}
	curve := ecdh.P256()
	key, err := curve.NewPrivateKey(priv)
	if err != nil {
		return fmt.Errorf("VAPID_PRIVATE_KEY is not a P-256 scalar: %w", err)
	}
	if !bytes.Equal(key.PublicKey().Bytes(), pub) {
		return fmt.Errorf("VAPID_PUBLIC_KEY does not match VAPID_PRIVATE_KEY")
	}
	return nil
}

func getenv(name string) string {
	return strings.TrimSpace(os.Getenv(name))
}

// Enabled reports whether web push is configured on this instance.
func Enabled() bool {
	keysOnce.Do(loadKeys)
	return vapidPublic != "" && vapidPriv != ""
}

// PublicKey returns the base64url VAPID public key for client subscription.
func PublicKey() string {
	keysOnce.Do(loadKeys)
	return vapidPublic
}

// Subject returns the JWT sub claim the sender will use, in the exact form
// webpush-go transmits it (a bare contact becomes mailto:<contact>). Exposed so
// a push service rejection naming the token can be traced to the configured
// contact without reading environment variables off the host.
func Subject() string {
	keysOnce.Do(loadKeys)
	if contact == "" {
		return ""
	}
	if !strings.HasPrefix(contact, "https:") {
		return "mailto:" + contact
	}
	return contact
}

// GenerateVapidKeys creates a new base64url key pair (used by tooling/tests).
func GenerateVapidKeys() (publicKey, privateKey string, err error) {
	curve := ecdh.P256()
	priv, err := curve.GenerateKey(rand.Reader)
	if err != nil {
		return "", "", err
	}
	privBytes := priv.Bytes()
	if len(privBytes) != 32 {
		return "", "", errors.New("unexpected private key length")
	}
	return base64.RawURLEncoding.EncodeToString(priv.PublicKey().Bytes()),
		base64.RawURLEncoding.EncodeToString(privBytes), nil
}

// Delivery is what one endpoint's push service answered.
//
// Status is the HTTP status the service returned; 0 means the request never
// produced a response (DNS, TLS, timeout) and Err carries that cause instead.
type Delivery struct {
	Endpoint string
	Status   int
	Err      string
}

// OK reports whether the push service accepted the message for delivery.
func (d Delivery) OK() bool { return d.Status >= 200 && d.Status < 300 }

type SendResult struct {
	Sent    int
	Removed int
	Failed  int
	Stale   []string   // endpoints to delete (404/410 from the push service)
	Results []Delivery // one per subscription, in order
}

// Send delivers one payload to all subscriptions. Stale endpoints
// (gone/failing permanently) are reported so the caller can delete them.
// Failures are logged, never returned to the notification path: in-app
// notifications must not fail because push is misconfigured.
func Send(ctx context.Context, subs []Subscription, title, body, href string) SendResult {
	keysOnce.Do(loadKeys)
	res := SendResult{}
	if !Enabled() || len(subs) == 0 {
		return res
	}
	payload, err := marshalPayload(title, body, href)
	if err != nil {
		log.Printf("push: payload marshal failed: %v", err)
		return res
	}
	for _, sub := range subs {
		resp, err := webpush.SendNotification([]byte(payload), &webpush.Subscription{
			Endpoint: sub.Endpoint,
			Keys: webpush.Keys{
				P256dh: sub.P256DH,
				Auth:   sub.Auth,
			},
		}, &webpush.Options{
			Subscriber:      contact,
			VAPIDPublicKey:  vapidPublic,
			VAPIDPrivateKey: vapidPriv,
			TTL:             int((24 * time.Hour).Seconds()),
		})
		d := classify(sub.Endpoint, resp, err)
		res.Results = append(res.Results, d)
		switch {
		case d.OK():
			res.Sent++
		case isStaleStatus(d.Status):
			res.Stale = append(res.Stale, sub.Endpoint)
			res.Removed++
		default:
			res.Failed++
		}
		if !d.OK() {
			log.Printf("push: send to %s… failed: status=%d %s",
				trimEndpoint(sub.Endpoint), d.Status, d.Err)
		}
	}
	return res
}

// classify turns the push service's answer into an outcome.
//
// webpush-go returns the *http.Response verbatim from client.Do, and Go's HTTP
// client reports no error for an HTTP error status. Checking only `err`
// therefore counted a 403 (VAPID key mismatch) or a 410 (dead endpoint) as a
// successful send: the table said "subscribed", the inbox filled in-app, and
// the device stayed silent with nothing logged (#344).
func classify(endpoint string, resp *http.Response, err error) Delivery {
	d := Delivery{Endpoint: endpoint}
	if resp != nil {
		d.Status = resp.StatusCode
		// Drain before closing so the transport can reuse the connection;
		// the body carries the service's own error code as text.
		b, _ := io.ReadAll(io.LimitReader(resp.Body, maxPushErrorBody))
		_ = resp.Body.Close()
		if d.Status >= 300 {
			d.Err = strings.TrimSpace(string(b))
		}
	}
	if err != nil && d.Err == "" {
		d.Err = err.Error()
	}
	if resp == nil && err == nil {
		d.Err = "no response"
	}
	return d
}

func isStaleStatus(status int) bool {
	return status == http.StatusNotFound || status == http.StatusGone
}

func trimEndpoint(endpoint string) string {
	if len(endpoint) > 60 {
		return endpoint[:60]
	}
	return endpoint
}

func marshalPayload(title, body, href string) (string, error) {
	type payload struct {
		Title string `json:"title"`
		Body  string `json:"body"`
		Href  string `json:"href,omitempty"`
	}
	truncate := func(s string, n int) string {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	b, err := json.Marshal(payload{
		Title: truncate(title, maxPushTitle),
		Body:  truncate(body, maxPushBody),
		Href:  truncate(href, maxPushHref),
	})
	return string(b), err
}

const (
	maxPushTitle = 180
	maxPushBody  = 500
	maxPushHref  = 2048
	// maxPushErrorBody caps what we keep of a rejection body: enough for the
	// service's error code, not enough to store a page.
	maxPushErrorBody = 2048
)
